export function normalizeCrop(cropName) {
    if (!cropName) return "";
    const clean = String(cropName).trim().toLowerCase().replace(/\s+/g, " ");
    return CROP_ALIASES[clean] || clean;
}

/**
 * Returns localized crop name, e.g. "தக்காளி" in Tamil or "टमाटर" in Hindi
 */
export function getLocalizedCropName(cropName, language = "en") {
    if (!cropName) return "";
    const key = normalizeCrop(cropName);
    const cropData = CROP_TRANSLATIONS[key];
    if (cropData) {
        return cropData[language] || cropData.en || cropName;
    }
    return cropName;
}

/**
 * Returns user-friendly formatted title:
 * In English: "Tomato"
 * In regional language: "தக்காளி (Tomato)"
 */
export function formatCropTitle(cropName, language = "en") {
    if (!cropName) return "";
    const key = normalizeCrop(cropName);
    const cropData = CROP_TRANSLATIONS[key];
    if (!cropData) return cropName;

    const enName = cropData.en || cropName;
    const localized = cropData[language] || enName;

    if (language === "en" || localized.toLowerCase() === enName.toLowerCase()) {
        return enName;
    }

    return `${localized} (${enName})`;
}

export default {
    CROP_TRANSLATIONS,
    CROP_ALIASES,
    normalizeCrop,
    getLocalizedCropName,
    formatCropTitle
};
